#!/usr/bin/env node
/* Generates the crawlable Class 11 Physics Chapter 12 lesson. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const route='/class-11-physics/chapter-12-kinetic-theory/';
const title='Class 11 Physics Chapter 12: Kinetic Theory';
const assetHash=file=>createHash('sha256').update(fs.readFileSync(path.join(root,file))).digest('hex').slice(0,8);
const svg=(label,body,caption='')=>`<figure class="diagram-wrap"><svg viewBox="0 0 620 220" role="img" aria-label="${label}">${body}</svg>${caption?`<figcaption class="diagram-caption">${caption}</figcaption>`:''}</figure>`;
const diagrams=[
svg('Gas molecules collide elastically with the walls of a cubic container',`<path d="M120 35 380 35 470 80 210 80Z M120 35V155L210 200V80M210 200H470V80M120 155 380 155 470 200" fill="#fffbeb" stroke="#92400e" stroke-width="3"/><circle cx="270" cy="110" r="8" fill="#047857"/><circle cx="337" cy="130" r="7" fill="#b45309"/><path d="M280 108 375 80m-12-2 12 2-5 11M330 128 230 156m12 4-12-4 5-11" fill="none" stroke="#047857" stroke-width="3"/><text x="385" y="56">wall area A</text><text x="220" y="217">side ℓ</text><text x="294" y="101">molecule</text>`,`Elastic wall collisions reverse the normal velocity component and transfer momentum to the wall; the average transfer produces pressure.`),
svg('Random molecular paths and collisions in a gas',`<rect x="55" y="28" width="510" height="160" rx="8" fill="#f8fafc" stroke="#334155" stroke-width="3"/><path d="M100 60 190 95 250 56 340 102 430 66 510 111M110 153 175 120 255 165 330 130 420 166 510 132" fill="none" stroke="#047857" stroke-width="3"/><circle cx="190" cy="95" r="6" fill="#b45309"/><circle cx="340" cy="102" r="6" fill="#b45309"/><circle cx="175" cy="120" r="6" fill="#b45309"/><text x="71" y="18">molecules: random motion between collisions</text><text x="422" y="210">collisions change direction</text>`,`At ordinary conditions, molecules travel many molecular diameters between brief collisions. The ideal-gas model neglects forces except during collisions.`),
svg('Molecular degrees of freedom for monatomic, diatomic and polyatomic gases',`<circle cx="105" cy="96" r="19" fill="#ffedd5" stroke="#b45309" stroke-width="3"/><path d="M80 96H55m-9-8 9 8-9 8M130 96h25m9-8-9 8 9 8M105 70V42m-8 9 8-9 8 9M105 122v28m-8-9 8 9 8-9" stroke="#047857" stroke-width="2"/><text x="48" y="185">Monatomic</text><circle cx="300" cy="96" r="13" fill="#ffedd5" stroke="#b45309" stroke-width="2"/><circle cx="337" cy="96" r="13" fill="#ffedd5" stroke="#b45309" stroke-width="2"/><path d="M313 96H324M300 77V55M300 115v24M337 77V55M337 115v24" stroke="#047857" stroke-width="2"/><text x="260" y="185">Diatomic, linear</text><circle cx="500" cy="80" r="12" fill="#ffedd5" stroke="#b45309" stroke-width="2"/><circle cx="475" cy="112" r="12" fill="#ffedd5" stroke="#b45309" stroke-width="2"/><circle cx="525" cy="112" r="12" fill="#ffedd5" stroke="#b45309" stroke-width="2"/><path d="M489 90 482 102M511 90l7 12" stroke="#047857" stroke-width="3"/><text x="459" y="185">Non-linear</text><text x="45" y="25">translation: 3</text><text x="260" y="25">translation + rotation: 5</text><text x="445" y="25">translation + rotation: 6</text>`,`Each independent quadratic degree of freedom contributes ½kBT per molecule in the classical equipartition model.`)
];

const concepts=[
{id:'sec-12-1',head:'12.1 · Molecular nature of matter',intro:'A gas law links measurable bulk quantities to a picture of discrete molecules.',points:[
'Matter consists of molecules. Avogadro’s number NA≈6.02×10²³ mol⁻¹ counts molecules per mole; the molar mass divided by NA gives the mass of one molecule.',
'The ideal-gas equation is PV=μRT=NkBT, where μ is amount in moles, N=μNA, R=8.314 J mol⁻¹ K⁻¹ and kB=R/NA≈1.38×10⁻²³ J K⁻¹. Use absolute temperature.',
'At ordinary conditions, gas molecules are separated by distances much larger than their size. Their own volume and intermolecular forces are negligible compared with the container volume and kinetic energy, except during collisions.',
'The molecular volume fraction is roughly density of gas / density of liquid for the same material. For water vapour at 100 °C and 1 atm, 0.6/1000≈6×10⁻⁴: most of the volume is empty space.',
'Molecular masses are tiny and molecular number densities are huge. Water’s molecular mass is about 0.018/NA≈3×10⁻²⁶ kg; at liquid density its molecular volume is about 3×10⁻²⁹ m³, corresponding to a radius near 2 Å.'
],rev:['PV=μRT=NkBT; kB=R/NA.','For dilute gases, molecular volume and intermolecular forces are small corrections.','Water molecule: mass ≈3×10⁻²⁶ kg; radius ≈2 Å.'],figure:diagrams[1],examples:[
{badge:'NCERT Example 12.1',title:'Molecular volume fraction in water vapour',question:'The density of water is 1000 kg m⁻³. The density of water vapour at 100 °C and 1 atm pressure is 0.6 kg m⁻³. Estimate the ratio of molecular volume to total vapour volume.',steps:['For the same mass, volume is inversely proportional to density. The vapour occupies 1000/0.6 times the liquid volume.','In liquid water, molecules are closely packed, so molecular volume is approximately the total volume.','The fraction in vapour is therefore the inverse expansion ratio: 0.6/1000.'],answer:'6×10⁻⁴.'},
{badge:'NCERT Example 12.2',title:'Size of a water molecule',question:'Estimate the volume and radius of a water molecule using the data in Example 12.1.',steps:['A water molecule has mass 0.018/6×10²³≈3×10⁻²⁶ kg.','At density 1000 kg m⁻³ its volume is m/ρ≈3×10⁻²⁹ m³.','Model it as a sphere: V=(4/3)πr³, so r=[3V/(4π)]^(1/3).'],answer:'r≈2×10⁻¹⁰ m=2 Å.'},
{badge:'NCERT Example 12.3',title:'Mean separation of water molecules',question:'What is the average distance between atoms (interatomic distance) in water? Use the data in Examples 12.1 and 12.2.',steps:['The same mass occupies about 1.67×10³ times more volume as vapour than liquid.','Volume available per molecule rises by this factor, so a characteristic spacing rises by its cube root, approximately 12 (the text rounds the expansion to 10³, giving 10).','Using the textbook’s rounded estimate, separation is about 2×(10×2 Å).'],answer:'About 40 Å using the NCERT order-of-magnitude estimate.'}
]},
{id:'sec-12-2',head:'12.2–12.3 · Gas laws and ideal-gas behaviour',intro:'The gas laws are limiting relations; real gases approach them when dilute and warm.',points:[
'Boyle’s law: for fixed amount at fixed temperature, PV is constant. Charles’ law: at fixed pressure, V/T is constant. Avogadro’s law: at fixed P,T, V is proportional to molecule number N.',
'Combining these gives PV=μRT=NkBT. For a mixture of non-reacting ideal gases at common V,T, Ptotal=ΣPi (Dalton’s law); each Pi is the pressure that component would exert alone in the same volume and temperature.',
'Real gases deviate from PV=μRT because molecules have finite size and interact. The ideal limit is approached at low pressure (low number density) and high temperature, away from condensation.',
'For a fixed gas sample, PV/T is approximately constant in the ideal region. At low pressure, extrapolated PV/T tends to μR, independent of the gas species for equal mole amount.',
'A gas molecule’s speed depends on its mass at a given temperature: lighter molecules move faster. Equal partial-pressure ratios in the same vessel imply equal mole (and molecule-number) ratios, not equal mass densities.'
],rev:['Boyle: PV const; Charles: V/T const; Avogadro: V∝N at fixed P,T.','Ideal gas: PV=NkBT; mixture pressure is sum of partial pressures.','Ideal behaviour improves as pressure falls and temperature rises.'],figure:svg('Partial pressures add to give the pressure of an ideal-gas mixture',`<rect x="40" y="40" width="170" height="120" rx="8" fill="#fffbeb" stroke="#92400e" stroke-width="3"/><circle cx="85" cy="80" r="7" fill="#047857"/><circle cx="160" cy="118" r="7" fill="#047857"/><text x="92" y="105">gas 1: P₁</text><rect x="225" y="40" width="170" height="120" rx="8" fill="#fff7ed" stroke="#b45309" stroke-width="3"/><circle cx="270" cy="80" r="7" fill="#b45309"/><circle cx="350" cy="118" r="7" fill="#b45309"/><text x="275" y="105">gas 2: P₂</text><path d="M405 100h60m-10-9 10 9-10 9" stroke="#047857" stroke-width="3"/><rect x="470" y="40" width="110" height="120" rx="8" fill="#ecfdf5" stroke="#047857" stroke-width="3"/><text x="483" y="93">mixture</text><text x="480" y="119">P=P₁+P₂</text>`,`Dalton’s law follows by adding the ideal-gas contributions NᵢkBT/V.`),examples:[
{badge:'NCERT Example 12.4',title:'Neon–oxygen mixture',question:'A vessel contains neon and oxygen. Their partial pressures are in the ratio 3:2. Estimate the ratios of molecule numbers and mass densities. Atomic mass Ne=20.2 u; molecular mass O₂=32.0 u.',steps:['At common V,T, Pi=Ni kBT/V, so NNe/NO₂=PNe/PO₂=3/2.','Mass density ratio is (NNe mNe)/(NO₂ mO₂)=(3/2)(20.2/32.0).'],answer:'Number ratio 3:2; mass-density ratio ≈0.947:1.'}
]},
{id:'sec-12-3',head:'12.4 · Kinetic theory: pressure derivation',intro:'Pressure is the average normal momentum transfer from molecule–wall collisions.',points:[
'Model N molecules of mass m in a cube of side ℓ and volume V=ℓ³. Molecules move randomly; collisions with walls and one another are elastic, and intermolecular forces are negligible except during brief collisions.',
'For one molecule with velocity component vx toward a wall of area A=ℓ², an elastic collision reverses vx. Its momentum change is −2mvx; the wall receives impulse 2mvx.',
'In time Δt, molecules within distance vxΔt can reach the wall. Half move toward it, so the number striking is (1/2)nAvxΔt. Momentum transferred is (2mvx)(1/2 nAvxΔt)=nmAvx²Δt.',
'Force is momentum transfer per time; dividing by A gives pressure contribution nm⟨vx²⟩. Isotropy means ⟨vx²⟩=⟨vy²⟩=⟨vz²⟩=⟨v²⟩/3. Therefore P=(1/3)nm⟨v²⟩.',
'Since n=N/V, PV=(1/3)Nm⟨v²⟩=(2/3)Etr, where Etr=N(1/2)m⟨v²⟩ is total translational kinetic energy. Vessel shape does not affect the result; pressure is scalar in equilibrium.',
'Real molecular collisions do not change the steady velocity distribution, so the ensemble average remains valid. The ideal-gas model assumes collisions are brief and elastic.'
],rev:['Pressure derivation: impulse per collision × collision rate, divided by wall area.','P=(1/3)nm⟨v²⟩; PV=(2/3)Etr.','Isotropy gives one-third of mean-square speed in each direction.'],figure:diagrams[0],worked:'Derivation · For one wall, Δp per hit=2mvx and hits per Δt=(1/2)nAvxΔt. Thus F/A=nm⟨vx²⟩. Random isotropic motion gives ⟨vx²⟩=⟨v²⟩/3, so P=(1/3)nm⟨v²⟩.'},
{id:'sec-12-4',head:'12.4 · Temperature, molecular speed and mixtures',intro:'Kinetic theory gives temperature a direct microscopic meaning.',points:[
'Equate PV=(2/3)Etr with PV=NkBT: Etr=(3/2)NkBT and average translational kinetic energy per molecule=(1/2)m⟨v²⟩=(3/2)kBT.',
'The rms speed is vrms=√⟨v²⟩=√(3kBT/m)=√(3RT/M), where M is molar mass in kg mol⁻¹. At the same temperature, every ideal-gas species has the same mean translational kinetic energy, but lighter molecules have greater rms speed.',
'For a mixture, pressures add: P=(1/3)Σni mi⟨vi²⟩. Thermal equilibrium makes each species’ mean translational energy (3/2)kBT, yielding Dalton’s law.',
'Compression by a moving piston transfers energy to molecules through collisions; the mean kinetic energy and temperature rise. During expansion, gas molecules transfer energy to the receding piston and cool if no compensating heat enters.',
'At STP, 1 mol of an ideal gas occupies about 22.4 L. Always distinguish gauge pressure from absolute pressure in gas-law calculations: Pabsolute=Pgauge+Patmosphere.'
],rev:['⟨Ktrans⟩=(3/2)kBT, independent of gas identity.','vrms=√(3kBT/m)=√(3RT/M); at fixed T, vrms∝1/√M.','Gas-law calculations use absolute pressure and kelvin.'],examples:[
{badge:'NCERT Example 12.5',title:'Argon and chlorine at equal temperature',question:'A flask contains argon and chlorine in a 2:1 mass ratio at 27 °C. Find ratios of average kinetic energy per molecule and rms speeds. Atomic mass Ar=39.9 u; molecular mass Cl₂=70.9 u.',steps:['At equal temperature, each species has mean translational kinetic energy (3/2)kBT.','From (1/2)mvrms²=(3/2)kBT, vrms∝1/√m.'],answer:'Mean kinetic energies Ar:Cl₂=1:1; vrms(Ar)/vrms(Cl₂)=√(70.9/39.9)≈1.33. The mass proportion of the mixture does not change these ratios.'},
{badge:'NCERT Example 12.6',title:'Uranium hexafluoride isotope speeds',question:'Uranium has isotopes of masses 235 u and 238 u. In uranium hexafluoride, which isotope moves faster and what is the percentage speed difference?',steps:['Molecular masses are 235+6×19=349 u and 238+6×19=352 u.','At a fixed temperature, rms speed is inversely proportional to square root of molecular mass.','Relative speed difference is [√(352/349)−1]×100%.'],answer:'The ²³⁵UF₆ molecule is faster, by approximately 0.44%.'},
{badge:'NCERT Example 12.7',title:'Piston collisions and gas temperature',question:'(a) A ball rebounds from a bat moving toward it. Does it move faster or slower? (b) Explain why compression heats a gas. (c) What happens when compressed gas expands against a piston? (d) Does a heavy cricket bat help?',steps:['In the bat frame, the approaching ball’s speed is u+V. Elastic rebound reverses this relative velocity; transforming back gives rebound speed u+2V away from the wicket.','A piston moving inward is like the bat moving toward molecules: collisions increase their kinetic energy, raising temperature.','An expanding gas transfers energy to an outward-moving piston; its molecules lose mean kinetic energy and cool if heat does not enter.','A heavier bat is less slowed by impact and can transfer more momentum/energy to the ball.'],answer:'(a) Faster (for an ideal massive bat); (b) compression heats; (c) expansion can cool; (d) a heavier bat can deliver a faster rebound.'}
]},
{id:'sec-12-5',head:'12.5 · Law of equipartition of energy',intro:'At thermal equilibrium, quadratic energy terms share energy equally on average.',points:[
'For translation, ε=(1/2)mvx²+(1/2)mvy²+(1/2)mvz². Since the three directions are equivalent and ⟨ε⟩=(3/2)kBT, each term averages (1/2)kBT.',
'Equipartition law: each independent quadratic term in energy contributes (1/2)kBT per molecule at temperature T. A degree of freedom is an independent coordinate needed to specify motion/configuration.',
'A monatomic molecule has 3 translational degrees of freedom. A rigid linear diatomic molecule has 3 translational+2 rotational active degrees; rotation about its bond axis is negligible at ordinary temperatures in the classical treatment.',
'A rigid non-linear molecule has 3 translational+3 rotational degrees. Each vibrational mode has both quadratic kinetic and potential terms, contributing kBT when fully active.',
'Equipartition is a classical result. At low temperatures, quantum energy levels can freeze out rotational or vibrational modes; the effective number of active degrees depends on temperature.'
],rev:['Each active quadratic term contributes ½kBT per molecule.','Rigid molecule f: monatomic 3; linear 5; non-linear 6 (translation + rotation).','Each active vibration contributes kBT; quantum effects freeze modes at low T.'],figure:diagrams[2],worked:'Proof for translation · Isotropy makes the average of each of the three equal quadratic terms the same. Their sum is the mean translational energy (3/2)kBT. Dividing equally among x, y and z gives (1/2)kBT per translational degree of freedom.'},
{id:'sec-12-6',head:'12.6 · Specific heat capacities',intro:'Equipartition predicts heat capacities from the active molecular degrees of freedom.',points:[
'At constant volume, no expansion work is done, so heat raises internal energy. For f active quadratic degrees per molecule, U=(f/2)NkBT and CV=(f/2)R per mole.',
'For an ideal gas, CP−CV=R (Mayer relation): at constant pressure, added heat supplies internal-energy increase plus expansion work. For a monatomic gas, CV=3R/2 and CP=5R/2; γ=CP/CV=5/3.',
'A rigid diatomic gas at ordinary temperature has f=5, so CV=5R/2, CP=7R/2 and γ=7/5. At high temperature active vibrations add energy and raise heat capacity; at low T rotations/vibrations may be frozen out.',
'For non-linear polyatomic molecules with six active translational/rotational degrees, CV=3R and CP=4R classically; vibrational modes add further contributions when excited.',
'In a solid, each atom vibrates in three dimensions. Each direction has quadratic kinetic and potential energy, so mean energy is 3kBT per atom and U=3RT per mole. Neglecting small solid expansion work gives molar C≈3R (Dulong–Petit law).',
'The classical solid prediction works near room temperature for many solids but fails at low temperature and for some materials (including carbon near room temperature). Quantum theory explains the fall in heat capacity as vibrational modes freeze out.'
],rev:['Gas with f active quadratic terms: CV=fR/2; CP=CV+R; γ=CP/CV.','Monatomic: (CV,CP,γ)=(3R/2,5R/2,5/3); diatomic: (5R/2,7R/2,7/5).','Classical solid: U=3RT and C≈3R; quantum effects matter at low T.'],examples:[
{badge:'NCERT Example 12.8',title:'Heating helium in a fixed-volume cylinder',question:'A fixed-capacity 44.8 L cylinder contains helium at standard temperature and pressure. How much heat raises its temperature by 15.0 °C? Take R=8.31 J mol⁻¹ K⁻¹.',steps:['At STP, 22.4 L per mole means the cylinder contains 2 mol.','Helium is monatomic, so CV=3R/2. The cylinder is fixed-volume, so Q=nCVΔT.','Q=2×(3/2×8.31)×15.0.'],answer:'Q≈374 J.'}
]},
{id:'sec-12-7',head:'12.7 · Mean free path',intro:'Molecules move quickly, but frequent collisions interrupt their paths.',points:[
'For hard-sphere molecules of diameter d, a molecule moving at average speed ⟨v⟩ sweeps a collision cylinder of cross-section πd². In time Δt the swept volume is πd²⟨v⟩Δt.',
'At number density n, collision count in this simplified stationary-target model is nπd²⟨v⟩Δt. Thus mean time between collisions τ≈1/(nπd²⟨v⟩) and mean free path ℓ=⟨v⟩τ≈1/(nπd²).',
'Other molecules also move. Using their mean relative speed gives the more accurate mean free path ℓ=1/(√2 πnd²), collision rate ≈√2 nπd²⟨v⟩ and mean collision time τ≈ℓ/⟨v⟩.',
'Since n=P/(kBT), ℓ=kBT/(√2πd²P): mean free path increases with temperature and decreases with pressure and molecular diameter squared. In an evacuated tube it can approach the tube length.',
'At STP, air with d≈2 Å has ℓ≈2.9×10⁻⁷ m, about 1500 molecular diameters. Mean free path underlies diffusion, viscosity and thermal conduction.'
],rev:['Simple model: ℓ≈1/(nπd²); relative-motion correction: ℓ=1/(√2πnd²).','τ≈ℓ/⟨v⟩; n=P/(kBT).','Mean free path grows as density/pressure falls and is central to transport in gases.'],figure:svg('Collision cylinder swept out by a moving molecule',`<path d="M85 102H500" stroke="#047857" stroke-width="10" opacity=".22"/><path d="M85 102H500" stroke="#047857" stroke-width="2" stroke-dasharray="7 6"/><circle cx="85" cy="102" r="18" fill="#ffedd5" stroke="#b45309" stroke-width="3"/><circle cx="255" cy="69" r="18" fill="#fff7ed" stroke="#b45309" stroke-width="3"/><circle cx="365" cy="134" r="18" fill="#fff7ed" stroke="#b45309" stroke-width="3"/><path d="M108 101h360m-12-9 12 9-12 9" stroke="#047857" stroke-width="3"/><text x="190" y="42">diameter d</text><path d="M115 125V150M115 145H235M230 140l6 10-6 10" stroke="#92400e" stroke-width="2"/><text x="140" y="178">mean free path ℓ</text><text x="276" y="205">swept collision area = πd²</text>`,`A collision occurs when another molecular centre enters within distance d of the moving molecule’s centreline.`),examples:[
{badge:'NCERT Example 12.9',title:'Mean free path in water vapour',question:'Estimate the mean free path of a water molecule in water vapour at 373 K, using the STP air value ℓ≈2.9×10⁻⁷ m and the textbook assumptions.',steps:['Take molecular diameter approximately that used for air; thus ℓ∝1/n.','At fixed pressure, n∝1/T, so ℓ scales in proportion to T.','ℓ(373 K)≈2.9×10⁻⁷×373/273. The textbook rounds its STP value to 3×10⁻⁷ m.'],answer:'About 4×10⁻⁷ m.'}
]}
];

const exercises=[
{n:'12.1',c:'sec-12-1',tag:'molecular',q:'Estimate the fraction of molecular volume to the actual volume occupied by oxygen gas at STP. Take the diameter of an oxygen molecule to be 3 Å.',steps:['At STP, 1 mol occupies 22.4×10⁻³ m³. Molecule volume as a sphere: (π/6)d³=(π/6)(3×10⁻¹⁰)³ m³.','Molecular volume fraction is NA(πd³/6)/(22.4×10⁻³).'],ans:'About 3.8×10⁻⁴ (roughly 0.04%).'},
{n:'12.2',c:'sec-12-2',tag:'gaslaw',q:'Molar volume is the volume occupied by 1 mol of any (ideal) gas at standard temperature and pressure (STP: 1 atmospheric pressure, 0 °C). Show that it is 22.4 litres.',steps:['Use PV=μRT with μ=1 mol, T=273 K and P=1.01×10⁵ Pa.','V=RT/P=(8.31×273)/(1.01×10⁵) m³. Convert m³ to litres by multiplying by 1000.'],ans:'V≈2.25×10⁻² m³≈22.4 L (rounded textbook value).'},
{n:'12.3',c:'sec-12-2',tag:'gaslaw',q:'Figure 12.8 shows plots of PV/T versus P for 1.00×10⁻³ kg oxygen gas at two different temperatures. (a) What does the dotted plot signify? (b) Which is true: T₁>T₂ or T₁<T₂? (c) What is PV/T where the curves meet the y-axis? (d) Would hydrogen give the same intercept? If not, what mass of hydrogen gives the same intercept? (Molecular mass H₂=2.02 u, O₂=32.0 u, R=8.31 J mol⁻¹ K⁻¹.)',steps:['(a) The dotted line is the ideal-gas limit/extrapolation toward zero pressure. (b) The plot itself is needed to identify which labelled curve has the indicated finite-pressure trend; read T₁ and T₂ from Fig. 12.8.','(c) At P→0, PV/T=μR=(m/M)R for ideal gas. Oxygen amount is 1.00×10⁻³/0.0320 mol.','(d) Match μ for hydrogen: mH₂/MH₂=mO₂/MO₂, hence mH₂=(1.00×10⁻³)(2.02/32.0) kg.'],ans:'(c) ≈0.260 J K⁻¹. (d) No at equal masses; same intercept requires ≈6.31×10⁻⁵ kg=0.0631 g H₂. Part (b) depends on the supplied textbook graph.'},
{n:'12.4',c:'sec-12-4',tag:'kinetic',q:'An oxygen cylinder of volume 30 litre has an initial gauge pressure of 15 atm and a temperature of 27 °C. After some oxygen is withdrawn, the gauge pressure drops to 11 atm and its temperature drops to 17 °C. Estimate the mass of oxygen taken out (R=8.31 J mol⁻¹ K⁻¹, molecular mass O₂=32 u).',steps:['Convert gauge to absolute: P₁=16 atm and P₂=12 atm. V=0.030 m³; T₁=300 K, T₂=290 K.','For each state n=PV/(RT). Amount removed is Δn=V(P₁/T₁−P₂/T₂)/R, using pressure in Pa.','Mass removed=Δn×0.032 kg mol⁻¹.'],ans:'≈0.14 kg O₂ (using 1 atm=1.013×10⁵ Pa).'},
{n:'12.5',c:'sec-12-4',tag:'kinetic',q:'An air bubble of volume 1.0 cm³ rises from the bottom of a lake 40 m deep at a temperature of 12 °C. To what volume does it grow when it reaches the surface, which is at a temperature of 35 °C?',steps:['At the bottom, absolute pressure P₁=P₀+ρgh≈1.013×10⁵+1000×9.8×40 Pa. At surface P₂=P₀.','For a fixed amount of gas, V₂=V₁(P₁/P₂)(T₂/T₁). Use kelvin: 285 K and 308 K.'],ans:'About 5.3 cm³ (neglect surface tension and gas dissolution).'},
{n:'12.6',c:'sec-12-2',tag:'gaslaw',q:'Estimate the total number of air molecules (inclusive of oxygen, nitrogen, water vapour and other constituents) in a room of capacity 25.0 m³ at a temperature of 27 °C and 1 atm pressure.',steps:['Use PV=NkBT, with P=1.013×10⁵ Pa, V=25.0 m³, T=300 K.','N=PV/(kBT), where kB=1.38×10⁻²³ J K⁻¹.'],ans:'N≈6.1×10²⁶ molecules.'},
{n:'12.7',c:'sec-12-4',tag:'kinetic',q:'Estimate the average thermal energy of a helium atom at (i) room temperature (27 °C), (ii) the temperature on the surface of the Sun (6000 K), (iii) 10 million kelvin (typical stellar-core temperature).',steps:['Use mean translational thermal energy ⟨K⟩=(3/2)kBT.','Convert 27 °C to 300 K; substitute each temperature.','For electron-volts, divide joules by 1.602×10⁻¹⁹ J/eV.'],ans:'(i) 6.2×10⁻²¹ J ≈0.039 eV; (ii) 1.24×10⁻¹⁹ J≈0.78 eV; (iii) 2.07×10⁻¹⁶ J≈1.29 keV.'},
{n:'12.8',c:'sec-12-5',tag:'equipartition',q:'Three equal-capacity vessels have gases at the same temperature and pressure: neon (monatomic), chlorine (diatomic) and uranium hexafluoride (polyatomic). Do they contain equal numbers of molecules? Is rms speed the same? If not, where is it largest?',steps:['PV=NkBT: equal P,V,T gives equal N.','At equal T, vrms∝1/√molecule mass. Compare molar masses: Ne≈20.2, Cl₂≈70.9, UF₆≈238+6×19≈352 u.'],ans:'Equal molecule numbers; speeds are unequal. Neon has the largest rms speed.'},
{n:'12.9',c:'sec-12-4',tag:'kinetic',q:'At what temperature is the rms speed of an argon atom equal to the rms speed of a helium atom at −20 °C? (Atomic masses Ar=39.9 u, He=4.0 u.)',steps:['Set 3kBTAr/mAr=3kBTHe/mHe, so TAr/mAr=THe/mHe.','THe=253 K; TAr=253×39.9/4.0.'],ans:'TAr≈2525 K (about 2.5×10³ K).'},
{n:'12.10',c:'sec-12-7',tag:'meanfreepath',q:'Estimate the mean free path and collision frequency of a nitrogen molecule in a cylinder containing nitrogen at 2.0 atm and 17 °C. Take the radius of a nitrogen molecule to be about 1.0 Å. Compare collision time with the time the molecule moves freely between collisions (M(N₂)=28.0 u).',steps:['d=2r=2.0×10⁻¹⁰ m; n=P/(kBT), with P=2.026×10⁵ Pa and T=290 K.','Use ℓ=1/(√2πnd²), then vrms=√(3RT/M) with M=0.028 kg mol⁻¹.','Mean free time τ≈ℓ/vrms and collision frequency f≈1/τ. The duration of an individual collision is much shorter than τ; the ideal hard-sphere model treats it as negligible.'],ans:'n≈5.1×10²⁵ m⁻³; ℓ≈1.1×10⁻⁷ m; vrms≈508 m s⁻¹; τ≈2.2×10⁻¹⁰ s; f≈4.6×10⁹ s⁻¹. Exact collision duration needs an intermolecular-force model.'}
];
exercises[1].q='Molar volume is the volume occupied by 1 mol of any (ideal) gas at standard temperature and pressure (STP: 1 atmospheric pressure, 0 °C). Show that it is 22.4 litres.';
exercises[2].q='Figure 12.8 shows plot of PV/T versus P for 1.00×10⁻³ kg of oxygen gas at two different temperatures. (a) What does the dotted plot signify? (b) Which is true: T₁>T₂ or T₁<T₂? (c) What is the value of PV/T where the curves meet on the y-axis? (d) If we obtained similar plots for 1.00×10⁻³ kg of hydrogen, would we get the same value of PV/T at the point where the curves meet on the y-axis? If not, what mass of hydrogen yields the same value of PV/T (for low pressure, high temperature region of the plot)? (Molecular mass of H₂=2.02 u, of O₂=32.0 u, R=8.31 J mol⁻¹ K⁻¹.)';
exercises[7].q='Three vessels of equal capacity have gases at the same temperature and pressure. The first vessel contains neon (monatomic), the second contains chlorine (diatomic), and the third contains uranium hexafluoride (polyatomic). Do the vessels contain equal number of respective molecules? Is the root mean square speed the same in the three cases? If not, in which case is vrms the largest?';
exercises[8].q='At what temperature is the root mean square speed of an atom in an argon gas cylinder equal to the rms speed of a helium gas atom at −20 °C? (Atomic mass of Ar=39.9 u, of He=4.0 u.)';
exercises[9].q='Estimate the mean free path and collision frequency of a nitrogen molecule in a cylinder containing nitrogen at 2.0 atm and temperature 17 °C. Take the radius of a nitrogen molecule to be roughly 1.0 Å. Compare the collision time with the time the molecule moves freely between two successive collisions (Molecular mass of N₂=28.0 u).';
exercises[2].steps[0]='(a) The dotted line is the ideal-gas limit, where PV/T=μR is independent of pressure. (b) The T₁ curve lies closer to this ideal line, so T₁>T₂.';
exercises[2].ans='(b) T₁>T₂. (c) ≈0.260 J K⁻¹. (d) No; the same intercept requires ≈6.31×10⁻⁵ kg=0.0631 g H₂.';
exercises[9].steps[2]='Mean free time τ≈ℓ/vrms and frequency f≈1/τ. A rough duration for one collision is d/vrms; it is much shorter than τ.';
exercises[9].ans='n≈5.1×10²⁵ m⁻³; ℓ≈1.1×10⁻⁷ m; vrms≈508 m s⁻¹; τ≈2.2×10⁻¹⁰ s; f≈4.6×10⁹ s⁻¹. Collision duration d/vrms≈4×10⁻¹³ s, about 500 times shorter than the free-flight time.';

const quiz=[
['sec-12-1','The number of molecules in μ moles is:',['μ/NA','μNA','NA/μ','μR'],1,'One mole contains NA molecules.'],
['sec-12-1','Boltzmann constant is related to R by:',['R/NA','RNA','NA/R','R+NA'],0,'kB=R/NA.'],
['sec-12-1','The ideal-gas equation in molecule form is:',['PV=NkBT','PV=NRT','P=NkBT','PV=kBT/N'],0,'Use molecule count with kB.'],
['sec-12-2','At fixed temperature, Boyle’s law states:',['P/V=constant','PV=constant','P/T=constant','V/T=constant'],1,'For a fixed amount of gas, PV is constant.'],
['sec-12-2','Dalton’s law says the total pressure is:',['the largest partial pressure','the product of partial pressures','the sum of partial pressures','independent of gas amounts'],2,'Each ideal component contributes Pi.'],
['sec-12-2','Ideal-gas behaviour is approached at:',['high pressure and low T','low pressure and high T','high pressure and high T','low pressure and low T'],1,'Dilute, warm gases reduce intermolecular corrections.'],
['sec-12-3','In an elastic collision with a wall, the normal velocity component:',['reverses sign','becomes zero permanently','does not change','doubles'],0,'Tangential components remain unchanged.'],
['sec-12-3','Molecules striking a wall per Δt in the simple cube derivation are:',['nAvxΔt','½nAvxΔt','2nAvxΔt','nA/vxΔt'],1,'Only half of the molecules in the swept layer move toward the wall.'],
['sec-12-3','For isotropic molecular motion, ⟨vx²⟩ is:',['⟨v²⟩','⟨v²⟩/2','⟨v²⟩/3','3⟨v²⟩'],2,'The three equal component averages sum to ⟨v²⟩.'],
['sec-12-3','The kinetic-theory pressure equation is:',['P=nm⟨v²⟩','P=(1/3)nm⟨v²⟩','P=3nm⟨v²⟩','P=nkBT/3'],1,'Pressure is one-third density times mean molecular kinetic term.'],
['sec-12-4','Mean translational kinetic energy per ideal-gas molecule is:',['kBT','(3/2)kBT','(5/2)kBT','RT'],1,'Temperature sets the average translational energy.'],
['sec-12-4','At the same temperature, rms speed is greatest for:',['the heaviest molecule','the lightest molecule','all are equal','the gas at higher pressure'],1,'vrms∝1/√m.'],
['sec-12-4','Gas-law temperature must be measured in:',['°C','°F','K','any scale'],2,'The equation uses absolute temperature.'],
['sec-12-5','Each active quadratic degree contributes average energy:',['kBT','½kBT','3/2kBT','2kBT'],1,'Equipartition gives one-half kBT per quadratic term.'],
['sec-12-5','A rigid linear diatomic molecule has how many active translational and rotational degrees at ordinary temperature?',['3','4','5','6'],2,'Three translation plus two rotations.'],
['sec-12-5','A vibration with quadratic kinetic and potential terms contributes:',['½kBT','kBT','3/2kBT','2kBT'],1,'Both terms each contribute ½kBT.'],
['sec-12-6','For an ideal gas, Mayer relation is:',['CP−CV=R','CV−CP=R','CP+CV=R','CP/CV=R'],0,'Constant-pressure heating includes PV work.'],
['sec-12-6','Monatomic ideal-gas CV is:',['R/2','R','3R/2','5R/2'],2,'Three translational degrees give fR/2.'],
['sec-12-6','For a classical solid, Dulong–Petit predicts molar heat capacity:',['R','2R','3R','5R'],2,'Three-dimensional atomic vibrations give U=3RT.'],
['sec-12-6','Why can classical heat-capacity predictions fail at low temperature?',['mass changes','quantum modes freeze out','pressure is always zero','equipartition becomes exact'],1,'Quantum energy levels prevent all modes from being thermally active.'],
['sec-12-7','Mean free path varies with molecular diameter as:',['d²','1/d²','d','1/d'],1,'ℓ=1/(√2πnd²).'],
['sec-12-7','Number density of an ideal gas is:',['n=PV/kBT','n=P/kBT','n=kBT/P','n=PT/kB'],1,'From P=nkBT.'],
['sec-12-7','At fixed temperature, lowering pressure makes mean free path:',['shorter','longer','unchanged','zero'],1,'Lower pressure means lower number density.'],
['sec-12-7','At STP, air mean free path is roughly:',['2.9×10⁻⁷ m','2.9×10⁻¹⁰ m','2.9×10⁻³ m','2.9 m'],0,'It is about 1500 molecular diameters.'],
['sec-12-3','In an equilibrium gas, pressure acts:',['only on container walls','throughout the fluid, including across internal layers','only downward','only during collisions'],1,'An internal layer is in equilibrium because pressure acts on both sides.'],
['sec-12-1','For ordinary gases, intermolecular spacing is about:',['one thousand times molecular size','ten times interatomic spacing in liquids/solids','one metre','exactly equal to molecular size'],1,'The separation is not enormous compared with condensed matter spacing.'],
['sec-12-7','Which statement is generally true?',['⟨v²⟩=⟨v⟩²','⟨v²⟩ need not equal ⟨v⟩²','⟨v²⟩ is always zero','averaging commutes with squaring'],1,'The mean of a square is generally different from the square of a mean.']
];

