const model=`<section class="ncert-section" id="kinetic-model"><div class="section-header"><span class="section-num-badge">MODEL</span><h2>Molecules in a container</h2></div><p class="section-intro">Watch elastic wall collisions transfer momentum. Change the speed scale to see why higher temperature means greater mean kinetic energy; the particle paths are illustrative, not a molecular-scale numerical simulation.</p><article class="thermal-sim-card" data-kinetic-model><div class="kinetic-canvas" aria-label="Animated ideal gas molecules bouncing inside a container"></div><div class="thermal-sim-controls"><label for="speedScale">Molecular speed</label><output id="speedReadout">1.0×</output><input id="speedScale" type="range" min="5" max="20" value="10" aria-label="Molecular speed scale"></div><p class="thermal-sim-readout">Mean kinetic energy ∝ T; wall impacts transfer normal momentum.</p><button type="button" class="sim-btn" data-model-toggle aria-pressed="true">Pause animation</button></article></section>`;
const modelScript=`<script>document.addEventListener('DOMContentLoaded',()=>{const host=document.querySelector('[data-kinetic-model]'),canvas=host?.querySelector('.kinetic-canvas'),reduce=matchMedia('(prefers-reduced-motion: reduce)');if(!host||!canvas||reduce.matches||!window.THREE)return;const T=window.THREE,scene=new T.Scene();scene.background=new T.Color(0x0b1120);const camera=new T.PerspectiveCamera(45,1,.1,100);camera.position.set(0,3.2,8);const renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));canvas.appendChild(renderer.domElement);scene.add(new T.AmbientLight(0xffffff,1.5));const light=new T.DirectionalLight(0xffffff,1.4);light.position.set(3,5,4);scene.add(light);const box=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(5.6,3.4,3.2)),new T.LineBasicMaterial({color:0x94a3b8}));scene.add(box);const geo=new T.SphereGeometry(.09,10,8),materials=[0x34d399,0xf59e0b,0x5eead4,0xfbbf24].map(color=>new T.MeshStandardMaterial({color,roughness:.45})),particles=Array.from({length:20},(_,i)=>{const mesh=new T.Mesh(geo,materials[i%materials.length]);scene.add(mesh);return {mesh,p:[(Math.random()-.5)*5,(Math.random()-.5)*2.9,(Math.random()-.5)*2.7],v:[Math.random()-.5,Math.random()-.5,Math.random()-.5].map(n=>n*1.5)}});const slider=host.querySelector('#speedScale'),readout=host.querySelector('#speedReadout'),toggle=host.querySelector('[data-model-toggle]');let running=true,frame=0,last=0,visible=true;const resize=()=>{const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false)};const ro=new ResizeObserver(resize);ro.observe(canvas);resize();slider.addEventListener('input',()=>{const speed=Number(slider.value)/10;readout.value=speed.toFixed(1)+'×';readout.textContent=speed.toFixed(1)+'×'});toggle.addEventListener('click',()=>{running=!running;toggle.textContent=running?'Pause animation':'Resume animation';toggle.setAttribute('aria-pressed',String(running));if(running)frame=requestAnimationFrame(draw);else cancelAnimationFrame(frame)});const draw=time=>{if(!running||!visible)return;frame=requestAnimationFrame(draw);if(time-last<32)return;const dt=Math.min((time-last)/1000,.05);last=time;const speed=Number(slider.value)/10;for(const p of particles){for(let a=0;a<3;a++){p.p[a]+=p.v[a]*speed*dt;const lim=[2.7,1.6,1.5][a];if(Math.abs(p.p[a])>lim){p.p[a]=Math.sign(p.p[a])*lim;p.v[a]*=-1}}p.mesh.position.set(...p.p)}renderer.render(scene,camera)};const io=new IntersectionObserver(es=>{visible=es[0].isIntersecting;if(visible&&running)frame=requestAnimationFrame(draw);else cancelAnimationFrame(frame)},{threshold:.05});io.observe(host);if(!document.hidden)frame=requestAnimationFrame(draw);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelAnimationFrame(frame);else if(visible&&running)frame=requestAnimationFrame(draw)});addEventListener('pagehide',()=>{cancelAnimationFrame(frame);io.disconnect();ro.disconnect();geo.dispose();materials.forEach(m=>m.dispose());box.geometry.dispose();box.material.dispose();renderer.dispose();renderer.domElement.remove()},{once:true})},{once:true});
</script>`;

